import React, { useEffect, useState } from 'react';
import api from '../../api/axios';
import ConfirmModal from '../../components/ConfirmModal';

export default function PageHistorique() {
  const [connexions, setConnexions] = useState([]);
  const [loading, setLoading]       = useState(true);
  const [filtre, setFiltre]         = useState('TOUS');
  const [selection, setSelection]   = useState([]);
  const [confirmData, setConfirmData] = useState(null);

  useEffect(() => { fetchConnexions(); }, []);

  const fetchConnexions = () => {
    api.get('/connexions').then(r => { setConnexions(r.data); setLoading(false); });
  };

  const supprimerUne = (connexion) => {
    setConfirmData({
      message: `Supprimer cette entrée de connexion ?`,
      onConfirm: async () => {
        await api.delete(`/connexions/${connexion.id}`);
        setConnexions(prev => prev.filter(c => c.id !== connexion.id));
        setConfirmData(null);
      }
    });
  };

  const supprimerSelection = () => {
    if (selection.length === 0) return;
    setConfirmData({
      message: `Supprimer ${selection.length} entrée(s) sélectionnée(s) ?`,
      onConfirm: async () => {
        await api.post('/connexions/supprimer-selection', { ids: selection });
        setConnexions(prev => prev.filter(c => !selection.includes(c.id)));
        setSelection([]);
        setConfirmData(null);
      }
    });
  };

  const toggleSelection = (id) => {
    setSelection(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const filtrees = connexions.filter(c => {
    if (filtre === 'TOUS') return true;
    return c.statut === filtre;
  });

  const toutSelectionner = () => {
    if (selection.length === filtrees.length) setSelection([]);
    else setSelection(filtrees.map(c => c.id));
  };

  const totalSucces = connexions.filter(c => c.statut === 'SUCCÈS').length;
  const totalEchecs = connexions.filter(c => c.statut === 'ÉCHEC').length;

  if (loading) return <div style={S.loading}>Chargement...</div>;

  return (
    <div>
      {confirmData && <ConfirmModal message={confirmData.message} onConfirm={confirmData.onConfirm} onCancel={() => setConfirmData(null)} />}

      {/* Header */}
      <div style={S.header}>
        <div>
          <div style={S.headerTitle}>Historique des connexions</div>
          <div style={S.headerSub}>{connexions.length} entrée(s)</div>
        </div>
      </div>

      {/* Métriques */}
      <div style={S.metricsRow}>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#2ed573'}}/>
          <div style={S.mcardLabel}>CONNEXIONS RÉUSSIES</div>
          <div style={S.mcardVal}>{totalSucces}</div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#ff4757'}}/>
          <div style={S.mcardLabel}>TENTATIVES ÉCHOUÉES</div>
          <div style={S.mcardVal}>{totalEchecs}</div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#0099ff'}}/>
          <div style={S.mcardLabel}>TOTAL</div>
          <div style={S.mcardVal}>{connexions.length}</div>
        </div>
        <div style={S.mcard}>
          <div style={{...S.mcardBar, background:'#f5a623'}}/>
          <div style={S.mcardLabel}>TAUX D'ÉCHEC</div>
          <div style={S.mcardVal}>
            {connexions.length > 0 ? Math.round((totalEchecs / connexions.length) * 100) : 0}
            <span style={S.mcardUnit}>%</span>
          </div>
        </div>
      </div>

      {/* Toolbar */}
      <div style={S.toolbar}>
        <div style={S.filtres}>
          {['TOUS', 'SUCCÈS', 'ÉCHEC'].map(f => (
            <button
              key={f}
              style={{...S.filtreBtn, ...(filtre===f ? S.filtreBtnActive : {})}}
              onClick={() => setFiltre(f)}
            >
              {f === 'SUCCÈS' && <span style={{...S.filtreDot, background:'#2ed573'}}/>}
              {f === 'ÉCHEC'  && <span style={{...S.filtreDot, background:'#ff4757'}}/>}
              {f}
            </button>
          ))}
        </div>
      </div>

      {/* Barre de sélection */}
      <div style={S.selectionBar}>
        <div style={{display:'flex', alignItems:'center', gap:10}}>
          <input
            type="checkbox"
            checked={selection.length === filtrees.length && filtrees.length > 0}
            onChange={toutSelectionner}
            style={{accentColor:'#00d4aa', width:14, height:14, cursor:'pointer'}}
          />
          <span style={S.selectionText}>
            {selection.length > 0 ? `${selection.length} sélectionnée(s)` : `${filtrees.length} entrée(s)`}
          </span>
        </div>
        {selection.length > 0 && (
          <button style={S.btnSupprimerSel} onClick={supprimerSelection}>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/>
              <path d="M10 11v6M14 11v6M9 6V4h6v2"/>
            </svg>
            Supprimer la sélection ({selection.length})
          </button>
        )}
      </div>

      {/* Table */}
      <div style={S.card}>
        {filtrees.length === 0 ? (
          <div style={S.empty}>Aucune connexion trouvée</div>
        ) : (
          <table style={S.tbl}>
            <thead>
              <tr>
                <th style={{...S.th, width:32}}></th>
                <th style={S.th}>Horodatage</th>
                <th style={S.th}>Email</th>
                <th style={S.th}>IP</th>
                <th style={S.th}>Statut</th>
                <th style={{...S.th, width:40}}></th>
              </tr>
            </thead>
            <tbody>
              {filtrees.map(c => (
                <tr key={c.id} style={{background: selection.includes(c.id) ? 'rgba(0,212,170,0.04)' : 'transparent'}}>
                  <td style={S.td}>
                    <input
                      type="checkbox"
                      checked={selection.includes(c.id)}
                      onChange={() => toggleSelection(c.id)}
                      style={{accentColor:'#00d4aa', width:13, height:13, cursor:'pointer'}}
                    />
                  </td>
                  <td style={{...S.td, fontFamily:'monospace', fontSize:12, color:'#7a8394'}}>
                    {new Date(c.horodatage).toLocaleString('fr-FR')}
                  </td>
                  <td style={S.td}>{c.email_tente}</td>
                  <td style={{...S.td, fontFamily:'monospace', fontSize:12, color:'#7a8394'}}>
                    {c.ip || '—'}
                  </td>
                  <td style={S.td}>
                    <span style={{...S.pill, ...(c.statut === 'SUCCÈS' ? S.pillOk : S.pillErr)}}>
                      {c.statut}
                    </span>
                  </td>
                  <td style={S.td}>
                    <button style={S.btnCorbeille} onClick={() => supprimerUne(c)} title="Supprimer">
                      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/>
                        <path d="M10 11v6M14 11v6M9 6V4h6v2"/>
                      </svg>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

const S = {
  loading:         { color:'#7a8394', textAlign:'center', marginTop:40 },
  header:          { display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:20 },
  headerTitle:     { fontSize:15, fontWeight:600, color:'#e8eaf0' },
  headerSub:       { fontSize:12, color:'#7a8394', marginTop:4 },
  metricsRow:      { display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:14, marginBottom:20 },
  mcard:           { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'18px 20px', position:'relative', overflow:'hidden' },
  mcardBar:        { position:'absolute', top:0, left:0, right:0, height:2 },
  mcardLabel:      { fontFamily:'monospace', fontSize:10, color:'#4a5260', letterSpacing:1.5, textTransform:'uppercase', marginBottom:12 },
  mcardVal:        { fontSize:28, fontWeight:600, color:'#e8eaf0', fontFamily:'monospace' },
  mcardUnit:       { fontSize:13, color:'#7a8394', marginLeft:4 },
  toolbar:         { display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:10 },
  filtres:         { display:'flex', gap:6 },
  filtreBtn:       { display:'flex', alignItems:'center', gap:5, padding:'6px 12px', background:'transparent', border:'1px solid rgba(255,255,255,0.10)', borderRadius:6, color:'#7a8394', fontSize:11, cursor:'pointer', fontFamily:'monospace' },
  filtreBtnActive: { background:'rgba(0,212,170,0.10)', borderColor:'rgba(0,212,170,0.30)', color:'#00d4aa' },
  filtreDot:       { width:5, height:5, borderRadius:'50%', flexShrink:0 },
  selectionBar:    { display:'flex', alignItems:'center', justifyContent:'space-between', padding:'8px 14px', background:'rgba(255,255,255,0.02)', border:'1px solid rgba(255,255,255,0.06)', borderRadius:8, marginBottom:10 },
  selectionText:   { fontSize:12, color:'#7a8394', fontFamily:'monospace' },
  btnSupprimerSel: { display:'flex', alignItems:'center', gap:6, padding:'6px 12px', background:'rgba(255,71,87,0.08)', border:'1px solid rgba(255,71,87,0.20)', borderRadius:6, color:'#ff4757', fontSize:12, cursor:'pointer' },
  card:            { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'20px 22px' },
  empty:           { color:'#7a8394', textAlign:'center', padding:'40px 0', fontSize:13 },
  tbl:             { width:'100%', borderCollapse:'collapse' },
  th:              { textAlign:'left', fontFamily:'monospace', fontSize:10, color:'#4a5260', letterSpacing:1, textTransform:'uppercase', paddingBottom:12, borderBottom:'1px solid rgba(255,255,255,0.07)' },
  td:              { padding:'11px 0', borderBottom:'1px solid rgba(255,255,255,0.05)', color:'#e8eaf0', fontSize:13 },
  pill:            { display:'inline-flex', fontFamily:'monospace', fontSize:10, padding:'3px 8px', borderRadius:4 },
  pillOk:          { background:'rgba(46,213,115,0.15)',  color:'#2ed573' },
  pillErr:         { background:'rgba(255,71,87,0.15)',   color:'#ff4757' },
  btnCorbeille:    { padding:'5px', background:'rgba(255,71,87,0.08)', border:'1px solid rgba(255,71,87,0.18)', borderRadius:6, color:'#ff4757', cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center' },
};
